# Runtime v2 · DC Tư duy khai báo và tính chất của composable function
# Nguồn: Kunneth, Android UI Development with Jetpack Compose, Ch.2–3 (trang PDF 42–86); "Thinking in Compose" (developer.android.com, đọc 2026-11-22);
# how-compose-works.md (androidx-main @296313a4). Sim runtime.runs.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.runs ----------------
    m = lambda k, vi, en=None: a('m.runs.' + k, vi, en)
    m('title', 'Thân composable chạy bao nhiêu lần?', 'How many times does a composable body run?')
    m('overview', 'Người dùng bấm +1 bốn lần (lần 3 và 4 sát nhau). `Counter` có một side effect `sentCount++`: đặt trong THÂN hàm hay trong CALLBACK `onClick`. Bấm Step và so ba con số: số lần bấm, số lần thân chạy, số lần side effect chạy.', 'The user taps +1 four times (taps 3 and 4 back to back). `Counter` has a side effect `sentCount++`: placed in the function BODY or in the `onClick` CALLBACK. Press Step and compare three numbers: taps, body runs, side-effect runs.')
    m('wrapup', 'Thân composable chạy theo nhịp của Compose, không theo nhịp của người dùng. Nó chạy một lần cho composition đầu, một lần mỗi khi input đổi, mỗi frame khi đọc giá trị animation, và cả những lần bị hủy giữa chừng. Vì thế side effect đặt trong thân chạy 11 lần cho 4 lần bấm; đặt trong callback thì đúng 4.\nQuy tắc dễ nhớ: thân composable chỉ "mô tả" giao diện; việc "làm" thì để trong callback hoặc effect.',
      'A composable body runs at Compose\'s pace, not the user\'s. It runs once for the first composition, once whenever inputs change, every frame while it reads an animated value, and even in runs that get cancelled. So a side effect in the body runs 11 times for 4 taps; in the callback it runs exactly 4.\nRule of thumb: a composable body only "describes" the interface; "doing" belongs in a callback or an effect.')
    m('simp.1', 'Số frame animation (2 frame thêm cho mỗi lần bấm) là giả định của site; số thật phụ thuộc thời lượng animation và tốc độ màn hình.', 'The number of animation frames (2 extra frames per tap) is the site\'s assumption; the real number depends on the animation length and the display refresh rate.')
    m('simp.2', 'Bước "hủy recomposition" minh hoạ điều tài liệu nói Compose CÓ THỂ làm (recomposition lạc quan, có thể bị hủy và chạy lại); site không khẳng định runtime hủy đúng ở thời điểm này.', 'The "recomposition cancelled" step illustrates what the docs say Compose MAY do (optimistic recomposition can be cancelled and restarted); the site does not claim the runtime cancels at exactly this moment.')
    m('ctl.hint', 'Đổi vị trí side effect, rồi tắt animation, và so ba con số ở cuối.', 'Move the side effect, then turn off the animation, and compare the three numbers at the end.')
    m('ctl.where', 'Side effect `sentCount++` đặt ở', 'The side effect `sentCount++` is in')
    m('ctl.where.body', 'thân composable', 'the composable body')
    m('ctl.where.callback', 'callback onClick', 'the onClick callback')
    m('ctl.anim', 'Có animation scale', 'Scale animation on')
    m('diagramTitle', 'Từ cú bấm tới thân composable và side effect', 'From a tap to the composable body and the side effect')
    m('diagramDesc', 'Người dùng, state, Recomposer, thân composable, màn hình, và nơi side effect ghi vào', 'User, state, Recomposer, composable body, screen, and where the side effect writes')
    for k, vi, en in [('tap', 'Người dùng bấm', 'User taps'), ('state', 'count (MutableState)', 'count (MutableState)'), ('recomposer', 'Recomposer', 'Recomposer'),
                      ('body', 'Thân Counter(…)', 'Counter(…) body'), ('screen', 'Màn hình', 'Screen'), ('effect', 'sentCount (bên ngoài)', 'sentCount (outside)')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('taps', 'Số lần bấm', 'Taps'), ('runs', 'Thân đã chạy', 'Body runs'), ('effects', 'Side effect đã chạy', 'Side-effect runs'), ('shown', 'Màn hình hiện count', 'Screen shows count')]:
        m('met.' + k, vi, en)
    S = [
        ('first', 'Composition đầu tiên', 'The first composition', 'Màn hình mở: thân `Counter` chạy lần đầu với count = 0. Chưa ai bấm gì, nhưng thân đã chạy một lần (thân đã chạy: {runs}).', 'The screen opens: the `Counter` body runs for the first time with count = 0. Nobody has tapped yet, but the body has already run once (body runs: {runs}).'),
        ('tap', 'Bấm lần {n}', 'Tap {n}', 'Callback `onClick` chạy trên luồng main, đúng một lần cho một cú bấm. Nếu side effect nằm ở đây, nó chạy đúng một lần.', 'The `onClick` callback runs on the main thread, exactly once per tap. If the side effect lives here, it runs exactly once.'),
        ('tapFast', 'Bấm lần {n} (rất nhanh)', 'Tap {n} (very fast)', 'Một cú bấm sát ngay sau cú trước.', 'A tap right after the previous one.'),
        ('write', 'Ghi state: count = {n}', 'State write: count = {n}', '`onIncrement()` ghi `count`. Compose biết thân `Counter` đã đọc `count`, nên đánh dấu nó cần chạy lại (invalidate) và Recomposer lên lịch cho frame kế.', '`onIncrement()` writes `count`. Compose knows the `Counter` body read `count`, so it marks it as needing to run again (invalidates it), and the Recomposer schedules it for the next frame.'),
        ('recompose', 'Recompose: thân chạy với count = {count}', 'Recompose: the body runs with count = {count}', 'Thân chạy lại từ đầu với input mới và mô tả UI mới. Mọi dòng trong thân đều chạy, kể cả `sentCount++` nếu nó nằm ở đó (thân đã chạy: {runs}).', 'The body runs again from the top with the new input and describes the new UI. Every line in the body runs, including `sentCount++` if it is there (body runs: {runs}).'),
        ('anim', 'Animation: thân chạy thêm mỗi frame', 'Animation: the body runs again every frame', '`animateFloatAsState` đổi giá trị mỗi frame, và thân ĐỌC giá trị đó (để truyền vào `Modifier.scale`). Thân đọc nên thân chạy lại mỗi frame trong lúc animation chạy (ở đây 2 frame nữa; thân đã chạy: {runs}).', '`animateFloatAsState` changes its value every frame, and the body READS that value (to pass it to `Modifier.scale`). Because the body reads it, the body re-runs every frame while the animation runs (2 more frames here; body runs: {runs}).'),
        ('start3', 'Bắt đầu recompose với count = 3', 'Recomposition starts with count = 3', 'Recomposer bắt đầu chạy thân cho count = 3. Mọi dòng trong thân đã chạy, kể cả side effect nếu có.', 'The Recomposer starts running the body for count = 3. Every line in the body has run, including any side effect.'),
        ('cancel', 'Bấm lần 4 khi đang recompose: hủy và chạy lại', 'Tap 4 during recomposition: cancel and restart', 'count đổi thành 4 trước khi lượt cho 3 kịp áp lên màn hình. Recomposition là "lạc quan": Compose có thể bỏ kết quả lượt cũ và chạy lại với giá trị mới. Màn hình không bao giờ hiện 3, nhưng side effect trong thân của lượt bị bỏ ĐÃ chạy rồi.', 'count becomes 4 before the run for 3 reaches the screen. Recomposition is "optimistic": Compose may discard the old run\'s result and restart with the new value. The screen never shows 3, but a side effect in the discarded run\'s body HAS already happened.'),
        ('end', 'Kết thúc: so ba con số', 'The end: compare the three numbers', 'Số lần bấm: 4. Số lần thân chạy: {runs}. Số lần side effect chạy: {fx}. Màn hình hiện count = {count}.', 'Taps: 4. Body runs: {runs}. Side-effect runs: {fx}. The screen shows count = {count}.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('firstBody', 'Chưa bấm lần nào mà `sentCount` đã là 1: side effect trong thân chạy theo composition, không theo hành động của người dùng.', 'No tap yet and `sentCount` is already 1: a side effect in the body runs with composition, not with what the user does.'),
        ('anim', 'Đọc giá trị animation ngay trong composition làm thân chạy lại mỗi frame. Chương B7 chỉ cách dời việc đọc sang phase sau (`graphicsLayer { }`) để khỏi recompose.', 'Reading an animated value during composition makes the body re-run every frame. Chapter B7 shows how to move the read to a later phase (`graphicsLayer { }`) to avoid recomposing.'),
        ('cancelBody', 'Lượt bị hủy không để lại gì trên màn hình, nhưng `sentCount++` của nó vẫn còn: trạng thái app lệch khỏi những gì người dùng thấy.', 'The cancelled run leaves nothing on screen, but its `sentCount++` remains: the app state drifts from what the user sees.'),
        ('cancelCb', 'Side effect nằm trong callback nên lượt bị hủy không gây gì: chỉ có cú bấm thật mới tăng `sentCount`.', 'The side effect is in the callback, so the cancelled run does no harm: only real taps increase `sentCount`.'),
        ('end.body', 'Side effect trong thân đếm số lần THÂN CHẠY, không phải số lần người dùng bấm. Tắt animation thì con số khác hẳn: hành vi phụ thuộc vào chi tiết không liên quan.', 'A side effect in the body counts BODY RUNS, not user taps. Turn the animation off and the number changes completely: behaviour depends on an unrelated detail.'),
        ('end.callback', 'Side effect trong callback khớp đúng số lần bấm, dù thân chạy bao nhiêu lần.', 'A side effect in the callback matches the number of taps exactly, however many times the body runs.')]:
        m('co.' + k, vi, en)
    a('cap.runs', 'Vòng một cú bấm: người dùng → state → Recomposer → thân composable → màn hình. Cạnh từ thân tới "sentCount" là side effect trong thân; cạnh từ người dùng tới "sentCount" là side effect trong callback. So ba chỉ số ở trên sơ đồ.', 'The loop of one tap: user → state → Recomposer → composable body → screen. The edge from the body to "sentCount" is a side effect in the body; the edge from the user to "sentCount" is a side effect in the callback. Compare the three metrics above the diagram.')

    # ---------------- chương DC ----------------
    C = 'dc'
    a(C + '.title', 'Tư duy khai báo: từ View tới composable, và luật của thân composable', 'Thinking declaratively: from Views to composables, and the rules of a composable body')
    a(C + '.essence',
      'Hệ View là KIỂU MỆNH LỆNH (imperative): XML được inflate thành một cây đối tượng; muốn đổi UI, ta tìm từng view và gọi setter (`setText`, `visibility = GONE`). Càng nhiều view thể hiện cùng một dữ liệu, càng dễ quên cập nhật một chỗ hoặc gây trạng thái bất hợp lệ. Tính năng được chia sẻ qua KẾ THỪA (`Button` kế thừa `TextView`), nên khó ghép tính năng của hai nhánh.\n'
      'Compose là KIỂU KHAI BÁO (declarative): UI là kết quả của một hàm theo state. Về khái niệm, mỗi khi state đổi, cả màn hình được "tạo lại"; thực tế Compose chỉ chạy lại phần cần thiết và áp thay đổi tối thiểu. Hàm `@Composable` không trả về widget (trả `Unit`); nó PHÁT (emit) node vào cấu trúc nội bộ của Compose. Tính năng được ghép bằng hàm và modifier, không bằng kế thừa.\n'
      'Hệ quả quan trọng nhất cho người viết code: thân composable chạy theo nhịp của Compose, không theo nhịp của người dùng. Nó có thể chạy rất thường xuyên (mỗi frame animation), bị bỏ qua, bị hủy giữa chừng; tài liệu còn dặn viết như thể nó có thể chạy song song và theo thứ tự bất kỳ (hiện tại Compose chạy trên luồng main và chưa chạy song song). Vì vậy thân composable phải NHANH, IDEMPOTENT và KHÔNG SIDE EFFECT; việc có tác dụng ra ngoài đặt trong callback hoặc effect.',
      'The View system is IMPERATIVE: XML is inflated into an object tree; to change the UI we find each view and call setters (`setText`, `visibility = GONE`). The more views show the same data, the easier it is to forget one or create an illegal state. Features are shared through INHERITANCE (`Button` extends `TextView`), so it is hard to combine features from two branches.\n'
      'Compose is DECLARATIVE: the UI is the result of a function of state. Conceptually, whenever state changes the whole screen is "regenerated"; in practice Compose only re-runs what is needed and applies minimal changes. A `@Composable` function does not return a widget (it returns `Unit`); it EMITS nodes into Compose\'s internal structures. Features are combined with functions and modifiers, not inheritance.\n'
      'The most important consequence for whoever writes the code: a composable body runs at Compose\'s pace, not the user\'s. It may run very often (every animation frame), be skipped, be cancelled midway; the docs even ask you to write it as if it could run in parallel and in any order (today Compose runs on the main thread and does not run in parallel). So a composable body must be FAST, IDEMPOTENT and SIDE-EFFECT FREE; anything that affects the outside world belongs in a callback or an effect.')
    a(C + '.goal.g1', 'Đã thấy cú bấm đầu tiên và thân chạy theo nó', 'Saw the first tap and the body run that follows it')
    a(C + '.goal.g2', 'Đã so số lần bấm với số lần thân chạy tới cuối', 'Compared taps with body runs to the end')
    a(C + '.sim.runtime.runs', 'Thân chạy bao nhiêu lần', 'How many body runs')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    B(C, S, 1, 'predict', 'Bạn viết `Analytics.log("counter_shown")` ngay trong thân một composable `Counter`, với ý định "ghi một lần khi màn hình hiện". Người dùng mở màn hình rồi bấm +1 ba lần. Log được ghi mấy lần?', 'You write `Analytics.log("counter_shown")` right in the body of a `Counter` composable, meaning "log once when the screen appears". The user opens the screen and taps +1 three times. How many times is the log written?')
    B(C, S, 1, 'ans', 'Ít nhất bốn lần (composition đầu + ba lần recompose), và có thể nhiều hơn nhiều: nếu thân đọc giá trị animation thì mỗi frame thêm một lần; nếu một recomposition bị hủy thì lượt đó vẫn đã ghi log. Con số không phụ thuộc ý định của bạn mà phụ thuộc vào việc Compose chạy thân bao nhiêu lần. Chương này giải thích vì sao, và mô phỏng ở giữa chương cho bạn đếm.', 'At least four times (the first composition + three recompositions), and possibly many more: if the body reads an animated value, one more per frame; if a recomposition is cancelled, that run has still logged. The number does not depend on your intent but on how many times Compose runs the body. This chapter explains why, and the simulation in the middle lets you count.')

    S = 'view'
    a(C + '.sec.%s.title' % S, 'Hệ View: cây đối tượng và setter', 'The View system: an object tree and setters')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Trước Compose, giao diện Android được dựng bằng hệ View. Một file layout XML mô tả một cây: ConstraintLayout chứa TextView, EditText, Button. `setContentView` hay `inflate()` biến cây đó thành một cây ĐỐI TƯỢNG: mỗi thẻ là một lớp, mỗi thuộc tính là một trường.\nMuốn đổi giao diện, ta giữ tham chiếu tới view (`findViewById`, sau này là view binding) rồi gọi setter. Ví dụ màn hình chào hỏi: nút Done chỉ bật khi ô nhập có chữ. Vì vậy phải gọi `enableOrDisableButton()` cả lúc tạo màn hình LẪN trong `doAfterTextChanged`. Bấm Done thì phải tự ẩn ô nhập, ẩn nút, và đặt chữ cho lời chào.\nQuy tắc dễ nhớ: trong hệ View, bạn là người tự tay sửa từng view.',
      'Before Compose, Android interfaces were built with the View system. A layout XML file describes a tree: a ConstraintLayout holding a TextView, an EditText, a Button. `setContentView` or `inflate()` turns that tree into an OBJECT tree: each tag is a class, each attribute a field.\nTo change the interface, we keep references to views (`findViewById`, later view binding) and call setters. Take a greeting screen: the Done button is enabled only when the input has text. So `enableOrDisableButton()` must be called both when the screen is created AND in `doAfterTextChanged`. Tapping Done means hiding the input yourself, hiding the button, and setting the greeting text.\nRule of thumb: in the View system, you edit every view by hand.')
    B(C, S, 2, 'kt', 'binding.name.doAfterTextChanged { enableOrDisableButton() }   // nhớ gọi ở MỌI nơi dữ liệu đổi\nbinding.done.setOnClickListener {\n    val name = binding.name.text\n    if (name.isNotBlank()) {\n        binding.message.text = getString(R.string.hello, name)\n        binding.name.visibility = GONE                    // phần ẩn VẪN nằm trong cây\n        it.visibility = GONE\n    }\n}\nprivate fun enableOrDisableButton() { binding.done.isEnabled = binding.name.text.isNotBlank() }', 'binding.name.doAfterTextChanged { enableOrDisableButton() }   // remember to call it EVERYWHERE the data changes\nbinding.done.setOnClickListener {\n    val name = binding.name.text\n    if (name.isNotBlank()) {\n        binding.message.text = getString(R.string.hello, name)\n        binding.name.visibility = GONE                    // the hidden part is STILL in the tree\n        it.visibility = GONE\n    }\n}\nprivate fun enableOrDisableButton() { binding.done.isEnabled = binding.name.text.isNotBlank() }')
    B(C, S, 3, 'p', 'Cách làm đó gọi là kiểu mệnh lệnh (imperative): mọi thay đổi giao diện là một lệnh sửa thuộc tính của từng view liên quan.\nApp nhỏ thì ổn. App lớn thì bạn phải tự nhớ dữ liệu nào ứng với view nào. Tài liệu Android nêu hai rủi ro cụ thể. Một: dữ liệu hiện ở nhiều chỗ thì dễ quên cập nhật một chỗ. Hai: hai lần cập nhật có thể xung đột, ví dụ đặt giá trị cho một view vừa bị gỡ khỏi cây ([[src:cp-mental]]).\nGiống như tự tay sửa từng dòng trong một bảng tính không có công thức: sửa một ô thì phải nhớ sửa mọi ô liên quan.',
      'That approach is called imperative: every interface change is a command editing the properties of each related view.\nFine for a small app. In a big app you must remember which data maps to which view. The Android docs name two concrete risks. One: data shown in several places makes it easy to forget to update one of them. Two: two updates can conflict, for example setting a value on a view that was just removed from the tree ([[src:cp-mental]]).\nLike editing a spreadsheet with no formulas: change one cell and you must remember to change every related cell.')
    B(C, S, 4, 'p', 'Hệ View còn một hạn chế nữa: cách chia sẻ tính năng. Mọi view kế thừa `android.view.View`. `Button` kế thừa `TextView`, còn `ImageButton` kế thừa `ImageView`. Muốn một nút có cả chữ lẫn ảnh thì tổ tiên chung gần nhất chỉ là `View`, nên không lấy được tính năng của cả hai nhánh.\nTương tự, `View` biết padding nhưng margin lại nằm ở `ViewGroup`; muốn margin thì phải kế thừa luôn mọi thứ khác của `ViewGroup`. Gốc vấn đề: tái sử dụng diễn ra ở mức CẢ component, không tách riêng từng tính năng được.\nCompose chọn "ghép thay vì kế thừa" (composition over inheritance): ghép các khối nhỏ như hàm composable và modifier (`background()`, `clickable { }`).\nQuy tắc dễ nhớ: trong Compose, muốn thêm tính năng thì ghép thêm một khối, đừng tìm lớp cha.',
      'The View system has another limitation: how features are shared. Every view extends `android.view.View`. `Button` extends `TextView`, while `ImageButton` extends `ImageView`. For a button with both text and an image, the nearest common ancestor is only `View`, so you cannot get the features of both branches.\nLikewise, `View` knows padding but margins live in `ViewGroup`; to get margins you must also inherit everything else in `ViewGroup`. The root problem: reuse happens at the level of a WHOLE component; you cannot pull out single features.\nCompose chooses "composition over inheritance": combine small blocks such as composable functions and modifiers (`background()`, `clickable { }`).\nRule of thumb: in Compose, to add a feature, add a block; do not look for a parent class.')

    S = 'declare'
    a(C + '.sec.%s.title' % S, 'Khai báo: UI là hàm của state', 'Declarative: the UI is a function of state')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Kiểu khai báo (declarative) làm ngược lại. Về khái niệm, nó dựng lại cả màn hình từ đầu theo dữ liệu hiện tại, rồi chỉ áp những thay đổi thật sự cần. Dựng lại cả màn hình thì tốn thời gian, CPU và pin, nên Compose chọn khéo phần nào cần chạy lại ([[src:cp-mental]]).\nTa không giữ tham chiếu tới widget và không gọi setter; widget không lộ ra như đối tượng. Muốn giao diện đổi, ta gọi lại cùng hàm composable với tham số khác.\nVòng lặp là: sự kiện (`onClick`) báo cho logic của app; logic đổi state; các hàm composable được gọi lại với dữ liệu mới. Lần gọi lại đó gọi là RECOMPOSITION.\nQuy tắc dễ nhớ: giao diện là kết quả của một hàm với đầu vào là state; đổi state thì giao diện tự theo.',
      "The declarative style does the opposite. Conceptually, it rebuilds the whole screen from scratch from the current data, then applies only the changes that are really needed. Rebuilding the whole screen costs time, CPU and battery, so Compose cleverly picks which parts need to run again ([[src:cp-mental]]).\nWe keep no references to widgets and call no setters; widgets are not exposed as objects. To change the interface, we call the same composable function again with different arguments.\nThe loop is: an event (`onClick`) informs the app's logic; the logic changes state; composable functions are called again with the new data. That re-call is called RECOMPOSITION.\nRule of thumb: the interface is the output of a function whose input is state; change the state and the interface follows.")
    B(C, S, 2, 'kt', '@Composable\nfun Greeting(names: List<String>) {      // nhận dữ liệu\n    for (name in names) {                  // toàn bộ sức mạnh của Kotlin: vòng lặp, if, hàm phụ\n        Text("Hello $name")                // PHÁT (emit) UI bằng cách gọi composable khác\n    }\n}                                          // không trả về gì: kiểu trả về là Unit\n\nprintln(ColoredTextDemo(text = "Hello Compose"))   // in ra: kotlin.Unit', '@Composable\nfun Greeting(names: List<String>) {      // takes data\n    for (name in names) {                  // the full power of Kotlin: loops, ifs, helper functions\n        Text("Hello $name")                // EMITS UI by calling other composables\n    }\n}                                          // returns nothing: the return type is Unit\n\nprintln(ColoredTextDemo(text = "Hello Compose"))   // prints: kotlin.Unit')
    B(C, S, 3, 'p', 'Composable không trả về widget, vậy giao diện ở đâu ra? Hãy lần theo chuỗi gọi trong mã nguồn: `Text()` → `BasicText()` → `CoreText()` (internal) → `Layout()` → `ReusableComposeNode()`.\nHàm cuối cùng dùng `currentComposer` để tạo một node bằng một factory (`ComposeUiNode.Constructor`), hoặc dùng lại node cũ, rồi cập nhật nó. Node mang theo `MeasurePolicy`, `LayoutDirection`, `Density`, `Modifier`.\nVậy "phát giao diện" nghĩa là THÊM NODE vào cấu trúc dữ liệu bên trong Compose; từ đó mới dẫn tới thứ hiện lên màn hình. Lưu ý: `currentComposer` là chi tiết nội bộ, mã app không được gọi ([[src:rt-pkg]]). Chi tiết ở đây thuộc một phiên bản Compose cũ hơn; B6 xem lại ở phiên bản hiện tại.\nQuy tắc dễ nhớ: composable không "trả về" giao diện, nó "ghi" node vào một cái cây.',
      'A composable returns no widget, so where does the interface come from? Follow the call chain in the source code: `Text()` → `BasicText()` → `CoreText()` (internal) → `Layout()` → `ReusableComposeNode()`.\nThat last function uses `currentComposer` to create a node with a factory (`ComposeUiNode.Constructor`), or reuse the old node, then updates it. The node carries a `MeasurePolicy`, a `LayoutDirection`, a `Density`, a `Modifier`.\nSo "emitting interface" means ADDING A NODE to Compose\'s internal data structures; that is what eventually leads to something on screen. Note: `currentComposer` is an internal detail that app code must not call ([[src:rt-pkg]]). The details here are from an older Compose version; B6 revisits them at the current version.\nRule of thumb: a composable does not "return" interface; it "writes" nodes into a tree.')
    B(C, S, 4, 'p', 'Có những composable TRẢ VỀ giá trị, vì việc lấy giá trị đó phải đi theo cơ chế composition. Ví dụ `remember { }` (nhớ theo vị trí trong cây) và `stringResource()` (đọc `LocalContext.current.resources`).\nQuy ước đặt tên theo đó mà khác nhau. Composable phát giao diện đặt tên như danh từ, viết PascalCase (`FancyDemo`). Composable trả về giá trị đặt tên như động từ, viết camelCase (`rememberScrollState`) ([[src:book-kunneth]]).\nQuy tắc dễ nhớ: tên viết hoa đầu thì vẽ ra một thứ; tên viết thường đầu thì trả về một thứ.',
      'Some composables DO return values, because obtaining that value must follow composition mechanics. For example `remember { }` (remembered by position in the tree) and `stringResource()` (reads `LocalContext.current.resources`).\nNaming differs accordingly. Composables that emit interface are named like nouns, in PascalCase (`FancyDemo`). Composables that return a value are named like verbs, in camelCase (`rememberScrollState`) ([[src:book-kunneth]]).\nRule of thumb: a capitalised name draws something; a lower-case name returns something.')

    S = 'rules'
    a(C + '.sec.%s.title' % S, 'Năm điều về cách thân composable chạy', 'Five facts about how a composable body runs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tài liệu "Thinking in Compose" liệt kê những điều phải nhớ ([[src:cp-mental]]). Ba điều đầu:\n1. Recomposition BỎ QUA nhiều nhất có thể. Mỗi hàm và mỗi lambda composable có thể tự recompose một mình. Khi `header` đổi, Compose có thể nhảy thẳng vào lambda của `Column` mà không chạy lại hàm cha.\n2. Recomposition LẠC QUAN và có thể bị HỦY. Nếu tham số đổi thêm lần nữa trước khi lượt cũ xong, Compose có thể bỏ lượt cũ và chạy lại. Cây giao diện của lượt bị bỏ bị vứt đi, nhưng side effect của nó thì đã xảy ra rồi.\n3. Thân hàm có thể chạy RẤT THƯỜNG XUYÊN, tới mức mỗi frame animation một lần. Vì vậy nó phải nhanh: đọc cài đặt thiết bị trong thân có thể thành hàng trăm lần đọc mỗi giây.',
      'The "Thinking in Compose" doc lists what you must remember ([[src:cp-mental]]). The first three:\n1. Recomposition SKIPS as much as possible. Every composable function and lambda can recompose on its own. When `header` changes, Compose may jump straight into the `Column` lambda without re-running the parent function.\n2. Recomposition is OPTIMISTIC and may be CANCELLED. If parameters change again before the old run finishes, Compose may drop the old run and start over. The dropped run\'s interface tree is thrown away, but its side effects have already happened.\n3. The body may run VERY OFTEN, as often as once per animation frame. So it must be fast: reading device settings in the body could become hundreds of reads per second.')
    B(C, S, 2, 'p', 'Hai điều tiếp theo:\n4. Composable CÓ THỂ chạy song song. Tài liệu nói rõ: HIỆN TẠI composable chưa chạy song song, nhưng hãy viết mã như thể có thể. Compose được thiết kế cho đa luồng, và tương lai có thể dùng nhiều nhân: chạy trong một pool luồng nền, gọi hàm của ViewModel từ nhiều luồng cùng lúc.\n5. Composable có thể chạy theo THỨ TỰ BẤT KỲ. Trong `{ StartScreen(); MiddleScreen(); EndScreen() }`, đừng để `StartScreen` đặt một biến toàn cục cho `MiddleScreen` dùng.\nQuy tắc dễ nhớ: đừng giả định composable chạy lúc nào, bao nhiêu lần, theo thứ tự nào.',
      'Two more:\n4. Composables MAY run in parallel. The docs are clear: composables do NOT run in parallel TODAY, but write your code as if they could. Compose is designed for multithreading and may use several cores in the future: running in a pool of background threads, calling ViewModel functions from several threads at once.\n5. Composables may run in ANY ORDER. In `{ StartScreen(); MiddleScreen(); EndScreen() }`, do not let `StartScreen` set a global variable for `MiddleScreen` to use.\nRule of thumb: never assume when a composable runs, how many times, or in what order.')
    B(C, S, 3, 'p', 'Từ đó suy ra ba tính chất bắt buộc:\n• NHANH: việc nặng làm ngoài composition, ví dụ trong coroutine của ViewModel, rồi truyền kết quả vào làm tham số.\n• IDEMPOTENT (gọi lại bao nhiêu lần cũng như nhau): cùng tham số thì cho cùng giao diện; không dùng biến toàn cục hay `random()`.\n• KHÔNG SIDE EFFECT. Side effect là bất kỳ thay đổi nào phần còn lại của app nhìn thấy được: ghi thuộc tính của một đối tượng dùng chung, cập nhật một observable trong ViewModel, ghi SharedPreferences.\nViệc cần side effect thì kích hoạt từ callback (như `onClick`, luôn chạy trên luồng giao diện), hoặc từ các effect API (EF "Side effect và vòng đời").\nQuy tắc dễ nhớ: nhanh, lặp lại không sao, và không đụng tới thế giới bên ngoài.',
      'Three required properties follow:\n• FAST: heavy work happens outside composition, for example in a ViewModel coroutine, and the result is passed in as a parameter.\n• IDEMPOTENT (calling it again changes nothing): the same parameters give the same interface; no global variables or `random()`.\n• SIDE-EFFECT FREE. A side effect is any change the rest of the app can see: writing a property of a shared object, updating an observable in a ViewModel, writing SharedPreferences.\nWhen you need a side effect, trigger it from a callback (like `onClick`, which always runs on the interface thread), or from the effect APIs (EF "Side effects and lifecycle").\nRule of thumb: fast, safe to repeat, and hands off the outside world.')
    B(C, S, 4, 'predict', 'Trong mô phỏng ngay dưới, với side effect đặt trong thân và có animation, sau 4 lần bấm thì `sentCount` bằng bao nhiêu? Nếu tắt animation thì sao? Nếu dời vào callback thì sao?', 'In the simulation just below, with the side effect in the body and the animation on, what is `sentCount` after 4 taps? With the animation off? Moved into the callback?')
    B(C, S, 4, 'ans', 'Trong thân + animation: 11 (1 composition đầu + mỗi lần bấm 1 lượt + 2 frame animation, cộng lượt bị hủy). Tắt animation: 5. Trong callback: 4, bất kể animation. Chạy cả ba tổ hợp để kiểm.', 'Body + animation: 11 (1 first composition + one run per tap + 2 animation frames, plus the cancelled run). Animation off: 5. Callback: 4, regardless of the animation. Run all three combinations to check.')

    S = 'where'
    a(C + '.sec.%s.title' % S, 'Vậy việc có tác dụng ra ngoài đặt ở đâu?', 'So where does work with outside effects go?')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ví dụ của tài liệu: một công tắc được lưu vào SharedPreferences. Composable KHÔNG tự đọc hay ghi SharedPreferences. Nó chỉ nhận một `value` và một callback `onValueChanged`. Việc đọc và ghi nằm trong ViewModel, trong một coroutine nền ([[src:cp-mental]]).\nĐây cũng là dạng cơ bản của STATE HOISTING (đẩy state lên trên): truyền mọi dữ liệu ảnh hưởng tới composable qua tham số, và báo thay đổi ngược lên bằng một lambda (`onValueChange`), thay vì dùng biến toàn cục. SH "Quản lý state" đi sâu vào phần này.\nQuy tắc dễ nhớ: dữ liệu đi xuống bằng tham số, sự kiện đi lên bằng lambda.',
      'The docs\' example: a toggle saved to SharedPreferences. The composable does NOT read or write SharedPreferences itself. It only takes a `value` and an `onValueChanged` callback. Reading and writing live in the ViewModel, in a background coroutine ([[src:cp-mental]]).\nThis is also the basic form of STATE HOISTING (moving state up): pass all data that affects a composable as parameters, and report changes back up with a lambda (`onValueChange`), instead of using global variables. SH "Managing state" goes deep into this.\nRule of thumb: data flows down through parameters; events flow up through lambdas.')
    B(C, S, 2, 'kt', '@Composable\nfun SharedPrefsToggle(text: String, value: Boolean, onValueChanged: (Boolean) -> Unit) {\n    Row {\n        Text(text)\n        Checkbox(checked = value, onCheckedChange = onValueChanged)   // ghi đi qua callback\n    }\n}\n\n// ✗ Lỗi của tài liệu: biến cục bộ bị sửa trong lambda composable\n@Composable\nfun ListWithBug(myList: List<String>) {\n    var items = 0\n    Row {\n        Column { for (item in myList) { Card { Text("Item: $item"); items++ } } }   // side effect của lambda Card\n        Text("Count: $items")      // có thể hiện SAI: Card có thể chạy lại riêng, theo thứ tự khác\n    }\n}', '@Composable\nfun SharedPrefsToggle(text: String, value: Boolean, onValueChanged: (Boolean) -> Unit) {\n    Row {\n        Text(text)\n        Checkbox(checked = value, onCheckedChange = onValueChanged)   // writes go through the callback\n    }\n}\n\n// ✗ The docs\' bug: a local variable modified inside a composable lambda\n@Composable\nfun ListWithBug(myList: List<String>) {\n    var items = 0\n    Row {\n        Column { for (item in myList) { Card { Text("Item: $item"); items++ } } }   // a side effect of the Card lambda\n        Text("Count: $items")      // may show the WRONG number: Card can re-run on its own, in another order\n    }\n}')
    B(C, S, 3, 'ask', 'Vì sao `ListWithBug` có thể hiện sai dù hiện tại Compose chạy một luồng?', 'Why can `ListWithBug` show the wrong number even though Compose runs on one thread today?')
    B(C, S, 3, 'ans', 'Vì mỗi lambda composable (ở đây là lambda của `Card`) có thể recompose riêng: khi chỉ một `Card` cần chạy lại, `items++` chạy thêm mà `Text("Count")` không chạy lại, hoặc ngược lại `Text` chạy lại mà các `Card` được skip nên `items` giữ 0. Con số phụ thuộc vào phần nào được chạy, không phụ thuộc vào dữ liệu. Cách đúng: `Text("Count: ${myList.size}")`, tính từ input.', 'Because each composable lambda (here, the `Card` lambda) can recompose on its own: when only one `Card` needs to re-run, `items++` runs again while `Text("Count")` does not, or conversely `Text` re-runs while the `Card`s are skipped so `items` stays 0. The number depends on which parts ran, not on the data. The right way: `Text("Count: ${myList.size}")`, computed from the input.')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp khi chưa quen tư duy khai báo', 'Common bugs before thinking declaratively')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Dashboard analytics báo màn hình "Giỏ hàng" được xem gấp 40 lần số phiên thật.', 'The analytics dashboard reports the "Cart" screen viewed 40 times more than real sessions.')
    B(C, S, 1, 'cause', '`analytics.logScreen("cart")` nằm trong thân `CartScreen`. Thân chạy mỗi lần giỏ đổi, mỗi frame của animation số lượng, và cả những lượt bị hủy.', '`analytics.logScreen("cart")` sits in the `CartScreen` body. The body runs every time the cart changes, every frame of the quantity animation, and in cancelled runs too.')
    B(C, S, 1, 'fix', 'Ghi log theo vòng đời màn hình: `LaunchedEffect(Unit) { analytics.logScreen("cart") }` (chạy khi vào composition, chương EF), hoặc ghi ở tầng điều hướng/ViewModel.', 'Log per screen lifecycle: `LaunchedEffect(Unit) { analytics.logScreen("cart") }` (runs on entering composition, chapter EF), or log at the navigation/ViewModel layer.')
    B(C, S, 2, 'bug', 'Danh sách cuộn bị giật; profiler cho thấy `getSharedPreferences` và đọc file chiếm phần lớn thời gian của luồng main.', 'A list stutters while scrolling; the profiler shows `getSharedPreferences` and file reads taking most of the main thread\'s time.')
    B(C, S, 2, 'cause', 'Mỗi item đọc cài đặt ngay trong thân composable. Khi cuộn, item được compose liên tục, nên đọc đĩa nhiều lần mỗi frame trên luồng main.', 'Each item reads settings right in its composable body. While scrolling, items are composed constantly, so the disk is read many times per frame on the main thread.')
    B(C, S, 2, 'fix', 'Đọc một lần ở ViewModel/repository (coroutine nền, DataStore Flow), đưa kết quả vào như tham số hoặc qua `StateFlow`. Thân composable chỉ nhận dữ liệu đã sẵn.', 'Read once in the ViewModel/repository (a background coroutine, a DataStore Flow), pass the result in as a parameter or through a `StateFlow`. The composable body only receives ready data.')
    B(C, S, 3, 'bug', 'Tab giữa hiển thị tiêu đề rỗng, nhưng chỉ thỉnh thoảng.', 'The middle tab shows an empty title, but only sometimes.')
    B(C, S, 3, 'cause', '`StartScreen()` gán `currentTitle = "…"` (biến toàn cục) và `MiddleScreen()` đọc nó, dựa vào thứ tự gọi trong mã. Composable có thể chạy riêng lẻ hoặc theo thứ tự khác, nên có lúc `MiddleScreen` chạy mà `StartScreen` không chạy.', '`StartScreen()` sets `currentTitle = "…"` (a global) and `MiddleScreen()` reads it, relying on the call order in the code. Composables can run on their own or in another order, so sometimes `MiddleScreen` runs while `StartScreen` does not.')
    B(C, S, 3, 'fix', 'Mỗi composable tự đủ: truyền tiêu đề vào làm tham số từ state chung được hoist lên cha.', 'Make each composable self-contained: pass the title in as a parameter from shared state hoisted to the parent.')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Tìm mọi side effect và việc nặng trong composable này, rồi viết lại:', 'Find every side effect and every piece of heavy work in this composable, then rewrite it:')
    B(C, S, 1, 'exkt', '@Composable\nfun ProfileHeader(userId: String, vm: ProfileViewModel) {\n    val prefs = LocalContext.current.getSharedPreferences("p", 0)\n    val theme = prefs.getString("theme", "light")\n    vm.markSeen(userId)\n    val avatar = BitmapFactory.decodeFile("/data/…/$userId.png")\n    Text("Theme: $theme")\n    Image(avatar.asImageBitmap(), null)\n}')
    B(C, S, 1, 'hint', 'Ba vấn đề: đọc đĩa (SharedPreferences, file ảnh) trên luồng main mỗi lần chạy; `vm.markSeen` là side effect (cập nhật ViewModel); decode bitmap là việc nặng.', 'Three problems: disk reads (SharedPreferences, the image file) on the main thread on every run; `vm.markSeen` is a side effect (updating the ViewModel); decoding a bitmap is heavy work.')
    B(C, S, 1, 'sol', 'Đưa dữ liệu vào bằng tham số (theme, avatar đã decode, tải trong ViewModel bằng coroutine nền). `markSeen` chạy theo vòng đời bằng `LaunchedEffect(userId)` hoặc do ViewModel tự gọi khi tải hồ sơ. Thân còn lại chỉ mô tả UI.', 'Pass data in as parameters (theme, an already-decoded avatar, loaded by the ViewModel in a background coroutine). `markSeen` runs per lifecycle with `LaunchedEffect(userId)`, or the ViewModel calls it when loading the profile. What remains in the body only describes UI.')
    B(C, S, 1, 'solkt', '@Composable\nfun ProfileHeader(state: ProfileUiState, onShown: () -> Unit) {\n    LaunchedEffect(state.userId) { onShown() }      // side effect theo vòng đời (chương EF)\n    Text("Theme: ${state.theme}")\n    state.avatar?.let { Image(it, contentDescription = null) }\n}')
    B(C, S, 2, 'ex', 'Câu hỏi ngắn: composable `fun Total(items: List<Int>) { var s = 0; items.forEach { s += it }; Text("$s") }` có vi phạm luật "không side effect" không?', 'Short question: does the composable `fun Total(items: List<Int>) { var s = 0; items.forEach { s += it }; Text("$s") }` break the "no side effects" rule?')
    B(C, S, 2, 'sol', 'Không. `s` là biến cục bộ, được tạo mới mỗi lần thân chạy và chỉ được sửa trong CÙNG thân, không trong lambda composable con. Kết quả chỉ phụ thuộc `items`: idempotent. Khác với `ListWithBug`, ở đó biến bị sửa bên trong lambda `Card` (có thể recompose riêng). (`items.sum()` gọn hơn.)', 'No. `s` is a local variable, created fresh on every run of the body and modified only within the SAME body, not inside a child composable lambda. The result depends only on `items`: idempotent. Unlike `ListWithBug`, where the variable is modified inside the `Card` lambda (which can recompose on its own). (`items.sum()` is shorter.)')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Khác biệt cốt lõi giữa cách đổi UI của hệ View và của Compose là gì?', 'What is the core difference between how the View system and Compose change the UI?')
    B(C, S, 1, 'ans', 'View: giữ tham chiếu tới từng widget và gọi setter để sửa trạng thái nội bộ của nó (mệnh lệnh). Compose: không có tham chiếu widget; gọi lại hàm composable với dữ liệu mới, và Compose tự chạy lại phần cần thiết rồi áp thay đổi (khai báo).', 'View: keep references to each widget and call setters to modify its internal state (imperative). Compose: no widget references; call the composable function again with new data, and Compose re-runs what is needed and applies the changes (declarative).')
    B(C, S, 2, 'ask', 'Kể năm điều tài liệu dặn về cách thân composable chạy, và điều nào là "hiện chưa xảy ra".', 'List the five facts the docs give about how a composable body runs, and which one "does not happen yet".')
    B(C, S, 2, 'ans', 'Bỏ qua nhiều nhất có thể; lạc quan và có thể bị hủy; có thể chạy rất thường xuyên (mỗi frame); có thể chạy song song; có thể chạy theo thứ tự bất kỳ. "Song song" là điều hiện chưa xảy ra (Compose chạy trên luồng main), nhưng phải viết code như thể có thể.', 'Skips as much as possible; optimistic and may be cancelled; may run very often (every frame); may run in parallel; may run in any order. "In parallel" does not happen yet (Compose runs on the main thread), but code must be written as if it could.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Một hàm `@Composable` phát UI trả về kiểu gì?', 'What does a UI-emitting `@Composable` function return?',
         '`Unit`.', '`Unit`.', 'Nó phát node vào cấu trúc nội bộ của Compose thay vì trả về widget.', 'It emits nodes into Compose\'s internal structures instead of returning a widget.'),
        ('q2', 'Recomposition bị hủy thì side effect trong thân của lượt đó có bị hoàn tác không?', 'When a recomposition is cancelled, is the side effect in that run\'s body undone?',
         'Không.', 'No.', 'Compose chỉ bỏ cây UI của lượt đó; thay đổi bên ngoài đã xảy ra thì vẫn còn.', 'Compose only discards that run\'s UI tree; changes already made outside remain.'),
        ('q3', 'Việc đọc SharedPreferences nên đặt ở đâu?', 'Where should SharedPreferences reads go?',
         'Ngoài composition (ViewModel/repository, coroutine nền), rồi truyền kết quả vào.', 'Outside composition (ViewModel/repository, a background coroutine), then pass the result in.', 'Thân composable có thể chạy mỗi frame; đọc đĩa ở đó làm giật UI.', 'A composable body may run every frame; disk reads there cause jank.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
